{"hypotheses": [
  {
    "name": "Post-Event Cash Squeeze",
    "mechanism": "Combining OrderBacklogChg and DelNWC captures firms that increase order backlog but show a decline in net working capital, implying aggressive booking of sales without matching liquidity. This identifies situations of operational strain following demand shocks, which may lead to forced asset sales or underperformance as working capital needs bite, above and beyond either indicator alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrderBacklogChg"},
        {"weight": -0.5, "primitive": "DelNWC"},
        {"weight": 0.5, "primitive": "CashProd"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "OrderBacklogChg", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.83,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Conglomerate Discount Rotation",
    "mechanism": "Firms with high retConglomerate but low HerfAsset are diversified yet operate in fragmented industries, positioning them to exploit capital misallocation cycles. This blend isolates mispricings from inefficient internal capital markets that are not captured by conglomerate discount or industry structure in isolation.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "retConglomerate"},
        {"weight": -1.0, "primitive": "HerfAsset"},
        {"weight": 0.5, "primitive": "DelCOA"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "HerfAsset", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Analyst Disagreement Overhang",
    "mechanism": "This composite combines high ForecastDispersion and high Recomm_ShortInterest, but penalizes positive AnalystRevision. It seeks firms where analysts disagree, short interest is high, and positive earnings revisions are ignored by the market due to skepticism, anticipating mean reversion once uncertainty fades.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 0.5, "primitive": "Recomm_ShortInterest"},
        {"weight": -1.0, "primitive": "AnalystRevision"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.78,
    "expected_decay_half_life_months": 15
  },
  {
    "name": "Illiquidity-Induced Volatility Premium",
    "mechanism": "By combining Illiquidity, IdioVolAHT, and RealizedVol, the factor targets stocks where high trading frictions coincide with realized and idiosyncratic volatility. The mechanism posits that market makers charge excess premiums when both liquidity and volatility risks spike together, producing a premium above the sum of parts.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Illiquidity"},
        {"weight": 0.5, "primitive": "IdioVolAHT"},
        {"weight": 0.5, "primitive": "RealizedVol"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "Illiquidity", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 10
  },
  {
    "name": "Intangible Investment Mispricing",
    "mechanism": "Combining BrandInvest, PatentsRD, and IntanEP captures firms that invest heavily in brand and intellectual capital and are undervalued on intangible earnings-to-price. The market inefficiently ignores hidden value in intangibles, so their combination should outperform either alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": 1.0, "primitive": "PatentsRD"},
        {"weight": 0.5, "primitive": "IntanEP"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "opposite_sign"},
      {"type": "correlation", "primitive": "PatentsRD", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.67,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Tax Avoidance Crowding",
    "mechanism": "Combining Tax, ExclExp, and CompositeDebtIssuance identifies firms aggressively lowering taxable income via special exclusions and leverage. The joint presence signals tax avoidance so aggressive that it draws regulatory and investor scrutiny, creating unique future revaluation risk.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Tax"},
        {"weight": -0.5, "primitive": "ExclExp"},
        {"weight": 1.0, "primitive": "CompositeDebtIssuance"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "Tax", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.62,
    "expected_decay_half_life_months": 16
  },
  {
    "name": "IPO Relisting Dislocation",
    "mechanism": "Firms with recent IPOs (AgeIPO) that switch exchanges (ExchSwitch) and exhibit high zerotrade6M experience compounded frictions: price discovery is poor and liquidity is thin. This combination creates transient mispricings not present in any single signal.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AgeIPO"},
        {"weight": 1.0, "primitive": "ExchSwitch"},
        {"weight": 0.5, "primitive": "zerotrade6M"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "ExchSwitch", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Organizational Capital Shock Absorbers",
    "mechanism": "A composite of OrgCap, LRreversal, and OrderBacklog isolates firms with high organizational capital that absorb or exploit long-run sector shocks better than peers. These firms display a unique ability to convert adversity into outperformance, an effect only captured in this blend.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 0.5, "primitive": "LRreversal"},
        {"weight": 0.5, "primitive": "OrderBacklog"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.66,
    "expected_decay_half_life_months": 20
  }
]}
